# Task management enums and models
class TaskStatus(str, Enum):
    pending = "pending"
    waiting = "waiting"  # Waiting for dependent task to complete
    running = "running"
    paused = "paused"
    completed = "completed"
    cancelled = "cancelled"
    failed = "failed"


class TaskLabel(str, Enum):
    """Task type labels for categorizing security activities."""
    general = "general"           # General questions and tasks
    pentest_web = "pentest_web"   # Web application penetration test
    pentest_api = "pentest_api"   # API penetration test
    pentest_network = "pentest_network"  # Network/infrastructure pentest
    pentest_osint = "pentest_osint"  # OSINT-focused assessment
    pentest = "pentest"           # Generic pentest (when type unclear)
    scanning = "scanning"         # Vulnerability scanning
    recon = "recon"               # Reconnaissance / OSINT
    discovery = "discovery"       # Asset discovery / Scoping


class Task(BaseModel):
    id: str
    name: Optional[str] = None  # Human-readable task name
    prompt: str
    status: TaskStatus
    created_at: datetime
    started_at: Optional[datetime] = None
    completed_at: Optional[datetime] = None
    result: Optional[str] = None
    error: Optional[str] = None
    tool_count: int = 0
    step_count: int = 0
    # Task classification
    label: TaskLabel = TaskLabel.general  # Task type label
    target_type: Optional[str] = None  # "web", "network", "api", "mobile", etc.
    # Report fields
    report_html: Optional[str] = None  # Generated HTML report
    report_markdown: Optional[str] = None  # Generated Markdown report
    # Task chaining fields
    depends_on: Optional[str] = None  # Task ID this task depends on
    chain_id: Optional[str] = None  # Chain identifier for grouped tasks
    chain_order: int = 0  # Order in the chain
    use_previous_result: bool = False  # Whether to inject previous task result
    chain_name: Optional[str] = None  # Human-readable chain name


# Task chain management
class TaskChain(BaseModel):
    id: str
    name: str
    description: Optional[str] = None
    created_at: datetime
    status: TaskStatus
    tasks: list[str] = []  # Ordered list of task IDs
    current_task_index: int = 0


