@app.on_event("startup")
async def startup():
    global agent, api_keys_store
    async with startup_lock:
        if agent is None:
            # Load API keys from file/environment
            load_api_keys_from_file()
            # Load provider settings (before building agent)
            load_provider_settings_from_file()
            # Load chat history
            load_chats_from_file()
            # Load scheduled tasks
            load_scheduled_tasks_from_file()
            # Load custom context
            load_custom_context()
            # Load task chains
            load_chains_from_file()
            # Load database settings
            load_database_settings_from_file()
            # Initialize database connection if enabled
            initialize_database_connection()
            # Start scheduler
            start_scheduler()
            # Start chain monitor
            start_chain_monitor()
            # Start activity state cleanup thread
            start_activity_cleanup_thread()
            # Initialize task persistence (loads interrupted tasks)
            task_persistence = get_task_persistence()
            task_persistence.start_auto_save()
            resumable_tasks = task_persistence.get_resumable_tasks()
            print(f"[TaskPersistence] Initialized. Resumable tasks: {len(resumable_tasks)}")
            
            # Populate activity_state_store from persisted tasks so clients can restore them
            for task in resumable_tasks:
                # Convert steps to activity log format
                logs = []
                for step in task.steps:
                    step_type = step.step_type  # 'thought', 'tool', 'observation', etc.
                    if step_type == "thought" and step.content:
                        logs.append({"type": "thought", "title": "Thinking...", "content": step.content[:500]})
                    elif step_type == "tool" and step.tool_name:
                        logs.append({"type": "tool", "title": f"Using {step.tool_name}", "content": str(step.tool_args or "")[:300]})
                    elif step_type == "observation" and step.tool_result:
                        logs.append({"type": "observation", "title": "Tool Result", "content": str(step.tool_result)[:500]})
                
                update_activity_state(
                    task.task_id,
                    prompt=task.prompt[:200] if task.prompt else "",
                    status=task.status.value if hasattr(task.status, 'value') else str(task.status),
                    startTime=(task.started_at or task.created_at or time.time()) * 1000,
                    stepCount=task.current_step or 0,
                    toolCount=task.tool_count or 0,
                    taskLabel=task.task_label or "general",
                    targetType=task.target_type,
                    logs=logs  # Reconstructed from steps
                )
            if resumable_tasks:
                print(f"[ActivityState] Restored {len(resumable_tasks)} tasks to activity monitor")
            # Initialize VectorDB memory (if available)
            if VECTORDB_AVAILABLE:
                try:
                    memory_result = init_vectordb_memory()
                    print(f"[VectorDB] Memory initialized: {memory_result.get('status', 'unknown')}")
                except Exception as e:
                    print(f"[VectorDB] Memory initialization failed: {e}")
            else:
                print("[VectorDB] Not available - install with: pip install vectordb2")
            # Build agent
            agent = build_owasp_agent()


@app.on_event("shutdown")
async def shutdown():
    """Clean shutdown - mark running tasks as interrupted and save state."""
    print("[Shutdown] Marking running tasks as interrupted...")
    try:
        task_persistence = get_task_persistence()
        # Mark all running tasks as interrupted so they can be resumed
        running_tasks = task_persistence.get_all_tasks(status_filter=["running"])
        for task in running_tasks:
            task_persistence.mark_interrupted(task.task_id)
            print(f"[Shutdown] Marked task {task.task_id} as interrupted")
        # Stop auto-save and flush any pending changes
        task_persistence.stop_auto_save()
        print(f"[Shutdown] Saved {len(running_tasks)} interrupted tasks for recovery")
    except Exception as e:
        print(f"[Shutdown] Error saving task state: {e}")


