@app.get("/api/projects/{project_id}/dashboard")
async def get_project_dashboard(project_id: str):
    """Get comprehensive project dashboard data including tasks, findings, and statistics."""
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    project = index["projects"][project_id]
    task_ids = project.get("tasks", [])
    tasks_data = index.get("tasks", {})
    
    # Collect all reports and findings for this project
    all_reports = []
    all_findings = []
    tool_outputs = []
    severity_counts = {"critical": 0, "high": 0, "medium": 0, "low": 0, "info": 0}
    
    # Get vulnerabilities from project vulndb
    vulndb = project.get("vulndb", [])
    for vuln in vulndb:
        sev = vuln.get("severity", "info").lower()
        if sev in severity_counts:
            severity_counts[sev] += 1
    
    # Collect task data
    tasks_list = []
    for task_id in task_ids:
        task = tasks_data.get(task_id, {})
        task_reports = []
        
        # Find all reports for this task
        for report_entry in index.get("reports", []):
            if report_entry.get("task_id") == task_id:
                report_path = Path(report_entry.get("path", ""))
                if report_path.exists():
                    try:
                        stat = report_path.stat()
                        task_reports.append({
                            "name": report_path.name,
                            "path": str(report_path),
                            "type": report_path.suffix.lower().lstrip('.'),
                            "size": stat.st_size,
                            "modified": datetime.fromtimestamp(stat.st_mtime).isoformat()
                        })
                    except:
                        pass
        
        tasks_list.append({
            "id": task_id,
            "prompt": task.get("prompt", "Unknown task"),
            "label": task.get("label", "general"),
            "created_at": task.get("created_at"),
            "report_count": len(task_reports),
            "reports": task_reports
        })
    
    # Build dashboard response
    dashboard = {
        "project": {
            "id": project_id,
            "name": project.get("name"),
            "description": project.get("description"),
            "color": project.get("color"),
            "created_at": project.get("created_at")
        },
        "statistics": {
            "total_tasks": len(tasks_list),
            "total_reports": sum(t["report_count"] for t in tasks_list),
            "total_vulnerabilities": len(vulndb),
            "severity_counts": severity_counts
        },
        "tasks": tasks_list,
        "vulndb": vulndb,
        "latest_report": None
    }
    
    # Find latest HTML report
    for task in tasks_list:
        for report in task.get("reports", []):
            if report.get("type") == "html":
                if dashboard["latest_report"] is None or report.get("modified", "") > dashboard["latest_report"].get("modified", ""):
                    dashboard["latest_report"] = report
    
    return JSONResponse(dashboard)


@app.get("/api/projects/{project_id}/vulnerabilities")
async def get_project_vulnerabilities(project_id: str):
    """Get all vulnerabilities (VulnDB) for a project."""
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    project = index["projects"][project_id]
    vulndb = project.get("vulndb", [])
    
    # Sort by severity priority
    severity_order = {"critical": 0, "high": 1, "medium": 2, "low": 3, "info": 4}
    vulndb.sort(key=lambda v: severity_order.get(v.get("severity", "info").lower(), 5))
    
    return JSONResponse({"vulnerabilities": vulndb, "count": len(vulndb)})


async def auto_parse_task_findings_to_vulndb(project_id: str, task_id: str):
    """Auto-parse findings from task result to project VulnDB.
    
    This function analyzes the task's final_result and tool outputs
    to extract vulnerabilities and add them to the project's VulnDB.
    """
    import re
    
    index = load_reports_index()
    project = index.get("projects", {}).get(project_id)
    if not project:
        return 0
    
    # Get task data
    task = index.get("tasks", {}).get(task_id, {})
    
    # Load full task state from persistence
    try:
        persistence = get_task_persistence()
        task_state = persistence.load_task(task_id)
    except Exception:
        task_state = None
    
    # Collect all text to parse (final_result + any associated reports)
    texts_to_parse = []
    
    if task_state and task_state.final_result:
        texts_to_parse.append(str(task_state.final_result))
    if task.get("final_result"):
        texts_to_parse.append(str(task.get("final_result")))
    
    # Also look for reports associated with this task
    for report in index.get("reports", []):
        if report.get("task_id") == task_id:
            report_path = report.get("path", "")
            if report_path:
                try:
                    from pathlib import Path
                    report_file = Path(report_path)
                    if report_file.exists():
                        content = report_file.read_text(encoding='utf-8', errors='ignore')
                        texts_to_parse.append(content)
                except Exception:
                    pass
    
    if not texts_to_parse:
        return 0  # No data to parse
    
    combined_text = "\n".join(texts_to_parse)
    
    # Initialize VulnDB if needed
    if "vulndb" not in project:
        project["vulndb"] = []
    
    existing_titles = {v.get("title", "").lower() for v in project["vulndb"]}
    findings_added = 0
    
    # Pattern to extract findings from report-style output
    patterns = [
        # Pattern 1: HTML report finding-title class
        r'<(?:h3|div)[^>]*class="[^"]*finding-title[^"]*"[^>]*>([^<]+)</(?:h3|div)>',
        # Pattern 2: Finding header with severity class
        r'<div[^>]*class="[^"]*finding-header\s+(\w+)[^"]*"[^>]*>\s*<[^>]+>([^<]+)',
        # Pattern 3: Markdown findings with emoji or bullet
        r'(?:🟢|🟡|🟠|🔴|⚫|[-•*])\s*(?:#\d+\s*)?\[(\w+)\]\s*(.+?)(?:\n|$)',
        # Pattern 4: Numbered findings
        r'(?:Finding\s+)?#?\d+[.):]\s*\[?(\w+)\]?\s*[-–:]\s*(.+?)(?:\n|$)',
        # Pattern 5: HTML title in finding
        r'<span[^>]*class="[^"]*finding-title[^"]*"[^>]*>([^<]+)</span>',
    ]
    
    # Also extract from structured finding blocks
    finding_block_pattern = r'<div[^>]*class="[^"]*finding[^"]*"[^>]*>.*?<div[^>]*class="[^"]*finding-header\s+(\w+)[^"]*"[^>]*>.*?<(?:span|h3)[^>]*class="[^"]*finding-title[^"]*"[^>]*>([^<]+)</(?:span|h3)>'
    
    for match in re.finditer(finding_block_pattern, combined_text, re.IGNORECASE | re.DOTALL):
        severity, title = match.groups()
        title = title.strip()[:200]
        severity = severity.strip().lower()
        
        if title.lower() not in existing_titles:
            vuln_id = f"AUTO-{uuid.uuid4().hex[:6].upper()}"
            vulnerability = {
                "id": vuln_id,
                "title": title,
                "severity": severity if severity in ['critical', 'high', 'medium', 'low', 'info'] else 'info',
                "description": f"Auto-extracted from task report",
                "status": "open",
                "source_task": task_id,
                "auto_parsed": True,
                "created_at": datetime.now().isoformat()
            }
            project["vulndb"].append(vulnerability)
            existing_titles.add(title.lower())
            findings_added += 1
    
    # Try other patterns
    for pattern in patterns:
        matches = re.findall(pattern, combined_text, re.IGNORECASE | re.MULTILINE)
        for match in matches:
            if len(match) >= 2:
                # Extract title and severity
                if len(match) == 3:
                    _, title, severity = match
                elif len(match) == 2:
                    title, severity = match
                else:
                    continue
                
                title = title.strip()[:200]  # Cap title length
                severity = severity.strip().lower()
                
                # Normalize severity
                severity_map = {
                    'critical': 'critical', 'crit': 'critical', 'p1': 'critical',
                    'high': 'high', 'hi': 'high', 'p2': 'high',
                    'medium': 'medium', 'med': 'medium', 'moderate': 'medium', 'p3': 'medium',
                    'low': 'low', 'lo': 'low', 'minor': 'low', 'p4': 'low',
                    'info': 'info', 'informational': 'info', 'note': 'info', 'p5': 'info'
                }
                severity = severity_map.get(severity, 'info')
                
                # Skip if already exists
                if title.lower() in existing_titles:
                    continue
                
                # Add to VulnDB
                vuln_id = f"AUTO-{uuid.uuid4().hex[:6].upper()}"
                vulnerability = {
                    "id": vuln_id,
                    "title": title,
                    "severity": severity,
                    "description": f"Auto-extracted from task: {task.get('prompt', task_id)[:100]}",
                    "status": "open",
                    "source_task": task_id,
                    "auto_parsed": True,
                    "created_at": datetime.now().isoformat()
                }
                project["vulndb"].append(vulnerability)
                existing_titles.add(title.lower())
                findings_added += 1
    
    # Also check for common security issues in text
    common_issues = {
        r'missing\s+(?:http\s+)?(?:x-frame-options|security)\s*header': ('Missing X-Frame-Options Header', 'low'),
        r'x-frame-options\s+(?:header\s+)?(?:not\s+set|missing|is\s+not\s+present)': ('Missing X-Frame-Options Header', 'low'),
        r'x-content-type-options\s+(?:not\s+set|missing)': ('Missing X-Content-Type-Options Header', 'low'),
        r'outdated\s+openssh|openssh\s+\d+\.\d+': ('Outdated OpenSSH Version', 'medium'),
        r'outdated\s+apache|apache\s+(?:httpd\s+)?\d+\.\d+': ('Outdated Apache Version', 'medium'),
        r'outdated\s+nginx|nginx\s+\d+\.\d+': ('Outdated Nginx Version', 'medium'),
        r'server\s+(?:version|banner)\s+(?:disclosure|exposed|visible)': ('Server Version Disclosure', 'low'),
        r'outdated\s+(?:software|version|component)': ('Outdated Software Component', 'medium'),
        r'default\s+(?:credentials|password|admin)': ('Default Credentials', 'high'),
        r'sql\s+injection': ('SQL Injection', 'critical'),
        r'cross[- ]?site\s+scripting|xss': ('Cross-Site Scripting (XSS)', 'high'),
        r'cors\s+misconfiguration': ('CORS Misconfiguration', 'medium'),
        r'sensitive\s+data\s+exposure': ('Sensitive Data Exposure', 'high'),
        r'directory\s+listing\s+enabled': ('Directory Listing Enabled', 'low'),
        r'weak\s+(?:ssl|tls|cipher)': ('Weak SSL/TLS Configuration', 'medium'),
    }
    
    for pattern, (title, severity) in common_issues.items():
        if re.search(pattern, combined_text, re.IGNORECASE):
            if title.lower() not in existing_titles:
                vuln_id = f"AUTO-{uuid.uuid4().hex[:6].upper()}"
                vulnerability = {
                    "id": vuln_id,
                    "title": title,
                    "severity": severity,
                    "description": f"Auto-detected pattern in task result",
                    "status": "open",
                    "source_task": task_id,
                    "auto_parsed": True,
                    "created_at": datetime.now().isoformat()
                }
                project["vulndb"].append(vulnerability)
                existing_titles.add(title.lower())
                findings_added += 1
    
    if findings_added > 0:
        save_reports_index(index)
        print(f"[INFO] Auto-parsed {findings_added} findings from task {task_id} to project {project_id}")
    
    return findings_added


@app.post("/api/projects/{project_id}/vulnerabilities")
async def add_project_vulnerability(project_id: str, data: dict):
    """Add a vulnerability to the project's VulnDB."""
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    # Validate required fields
    required_fields = ["title", "severity", "description"]
    for field in required_fields:
        if not data.get(field):
            return JSONResponse({"error": f"Field '{field}' is required"}, status_code=400)
    
    project = index["projects"][project_id]
    if "vulndb" not in project:
        project["vulndb"] = []
    
    # Generate vulnerability ID
    vuln_id = f"VULN-{uuid.uuid4().hex[:8].upper()}"
    
    vulnerability = {
        "id": vuln_id,
        "title": data.get("title"),
        "severity": data.get("severity", "info").lower(),
        "description": data.get("description"),
        "impact": data.get("impact", ""),
        "remediation": data.get("remediation", ""),
        "owasp_category": data.get("owasp_category", ""),
        "cvss_score": data.get("cvss_score", ""),
        "cwe_id": data.get("cwe_id", ""),
        "affected_component": data.get("affected_component", ""),
        "evidence": data.get("evidence", ""),
        "steps_to_reproduce": data.get("steps_to_reproduce", ""),
        "tool_used": data.get("tool_used", ""),
        "command_used": data.get("command_used", ""),
        "references": data.get("references", ""),
        "screenshots": data.get("screenshots", []),
        "source": data.get("source", "manual"),  # 'manual' or 'agent'
        "created_at": datetime.now().isoformat(),
        "updated_at": datetime.now().isoformat()
    }
    
    project["vulndb"].append(vulnerability)
    save_reports_index(index)
    
    return JSONResponse({"success": True, "vulnerability": vulnerability})


@app.get("/api/projects/{project_id}/vulnerabilities/{vuln_id}")
async def get_project_vulnerability(project_id: str, vuln_id: str):
    """Get a specific vulnerability from the project's VulnDB."""
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    project = index["projects"][project_id]
    vulndb = project.get("vulndb", [])
    
    vuln = next((v for v in vulndb if v.get("id") == vuln_id), None)
    if not vuln:
        return JSONResponse({"error": "Vulnerability not found"}, status_code=404)
    
    return JSONResponse(vuln)


@app.put("/api/projects/{project_id}/vulnerabilities/{vuln_id}")
async def update_project_vulnerability(project_id: str, vuln_id: str, data: dict):
    """Update a vulnerability in the project's VulnDB."""
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    project = index["projects"][project_id]
    vulndb = project.get("vulndb", [])
    
    vuln_idx = next((i for i, v in enumerate(vulndb) if v.get("id") == vuln_id), None)
    if vuln_idx is None:
        return JSONResponse({"error": "Vulnerability not found"}, status_code=404)
    
    # Update fields
    vuln = vulndb[vuln_idx]
    update_fields = ["title", "severity", "description", "impact", "remediation", 
                     "owasp_category", "cvss_score", "cwe_id", "affected_component",
                     "evidence", "steps_to_reproduce", "tool_used", "command_used",
                     "references", "screenshots"]
    
    for field in update_fields:
        if field in data:
            vuln[field] = data[field]
    
    vuln["updated_at"] = datetime.now().isoformat()
    save_reports_index(index)
    
    return JSONResponse({"success": True, "vulnerability": vuln})


@app.delete("/api/projects/{project_id}/vulnerabilities/{vuln_id}")
async def delete_project_vulnerability(project_id: str, vuln_id: str):
    """Delete a vulnerability from the project's VulnDB."""
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    project = index["projects"][project_id]
    vulndb = project.get("vulndb", [])
    
    original_len = len(vulndb)
    project["vulndb"] = [v for v in vulndb if v.get("id") != vuln_id]
    
    if len(project["vulndb"]) == original_len:
        return JSONResponse({"error": "Vulnerability not found"}, status_code=404)
    
    save_reports_index(index)
    return JSONResponse({"success": True})


# ============== SCANNERS DATABASE API ==============

@app.get("/api/projects/{project_id}/scanners-db")
async def get_project_scanners_db(project_id: str):
    """Get scanners database summary for a project."""
    from pathlib import Path
    import json
    
    scanners_db_file = Path("reports/scanners_db.json")
    
    if not scanners_db_file.exists():
        return JSONResponse({
            "total_scans": 0,
            "pending_validations": 0,
            "scan_groups": {}
        })
    
    try:
        db = json.loads(scanners_db_file.read_text(encoding='utf-8'))
        project_data = db.get("projects", {}).get(project_id, {})
        
        if not project_data:
            return JSONResponse({
                "total_scans": 0,
                "pending_validations": 0,
                "scan_groups": {}
            })
        
        # Build summary by tool
        scan_groups = {}
        total_scans = 0
        pending_validations = 0
        
        for group_name, group_data in project_data.get("scan_groups", {}).items():
            scans = group_data.get("scans", [])
            scan_groups[group_name] = []
            
            for scan in scans:
                total_scans += 1
                scan_summary = {
                    "scan_id": scan.get("scan_id", ""),
                    "target": scan.get("target", ""),
                    "findings_count": scan.get("findings_count", 0),
                    "status": scan.get("status", "pending"),
                    "timestamp": scan.get("timestamp", "")
                }
                scan_groups[group_name].append(scan_summary)
                
                # Count pending validations
                if scan.get("status") == "pending":
                    pending_validations += scan.get("findings_count", 0)
        
        return JSONResponse({
            "total_scans": total_scans,
            "pending_validations": pending_validations,
            "scan_groups": scan_groups
        })
        
    except Exception as e:
        return JSONResponse({
            "total_scans": 0,
            "pending_validations": 0,
            "scan_groups": {},
            "error": str(e)
        })


@app.get("/api/projects/{project_id}/scanners-db/{scan_id}")
async def get_scan_result_detail(project_id: str, scan_id: str):
    """Get detailed scan result including raw output."""
    from pathlib import Path
    import json
    
    scanners_db_file = Path("reports/scanners_db.json")
    
    if not scanners_db_file.exists():
        return JSONResponse({"error": "Scanners database not found"}, status_code=404)
    
    try:
        db = json.loads(scanners_db_file.read_text(encoding='utf-8'))
        project_data = db.get("projects", {}).get(project_id, {})
        
        if not project_data:
            return JSONResponse({"error": "Project not found in scanners db"}, status_code=404)
        
        # Search for scan in all groups
        for group_name, group_data in project_data.get("scan_groups", {}).items():
            for scan in group_data.get("scans", []):
                if scan.get("scan_id") == scan_id:
                    return JSONResponse({
                        "scan_id": scan_id,
                        "tool": group_name,
                        "target": scan.get("target", ""),
                        "findings_count": scan.get("findings_count", 0),
                        "status": scan.get("status", "pending"),
                        "timestamp": scan.get("timestamp", ""),
                        "raw_output": scan.get("raw_output", ""),
                        "metadata": scan.get("metadata", {})
                    })
        
        return JSONResponse({"error": "Scan not found"}, status_code=404)
        
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


