def _generate_finding_html(finding: dict) -> str:
    """Generate HTML for a single finding."""
    severity = finding.get("severity", "info").lower()
    
    html = f"""
    <div class="finding">
        <div class="finding-header">
            <span class="severity-badge {severity}">{finding.get('severity', 'Info')}</span>
            <span class="finding-title">{finding.get('title', 'Untitled')}</span>
        </div>
        <div class="finding-body">
            <div class="finding-field">
                <label>Description</label>
                <div class="finding-field-content">{finding.get('description', 'N/A')}</div>
            </div>
    """
    
    if finding.get('affected_component') and finding.get('affected_component') != 'N/A':
        html += f"""
            <div class="finding-field">
                <label>Affected Component</label>
                <div class="finding-field-content"><code>{finding.get('affected_component')}</code></div>
            </div>
        """
    
    if finding.get('impact'):
        html += f"""
            <div class="finding-field">
                <label>Impact</label>
                <div class="finding-field-content">{finding.get('impact')}</div>
            </div>
        """
    
    if finding.get('evidence'):
        html += f"""
            <div class="finding-field">
                <label>Evidence</label>
                <pre>{finding.get('evidence')}</pre>
            </div>
        """
    
    if finding.get('steps_to_reproduce'):
        html += f"""
            <div class="finding-field">
                <label>Steps to Reproduce</label>
                <div class="finding-field-content" style="white-space: pre-wrap;">{finding.get('steps_to_reproduce')}</div>
            </div>
        """
    
    if finding.get('remediation'):
        html += f"""
            <div class="finding-field">
                <label>Remediation</label>
                <div class="finding-field-content">{finding.get('remediation')}</div>
            </div>
        """
    
    # Show metadata
    metadata = []
    if finding.get('owasp_category') and finding.get('owasp_category') != 'N/A':
        metadata.append(f"OWASP: {finding.get('owasp_category')}")
    if finding.get('cvss_score') and finding.get('cvss_score') != 'N/A':
        metadata.append(f"CVSS: {finding.get('cvss_score')}")
    if finding.get('cwe_id') and finding.get('cwe_id') != 'N/A':
        metadata.append(f"CWE: {finding.get('cwe_id')}")
    if finding.get('tool_used'):
        metadata.append(f"Tool: {finding.get('tool_used')}")
    
    if metadata:
        html += f"""
            <div class="finding-field" style="display: flex; gap: 1rem; flex-wrap: wrap;">
                {''.join(f'<span style="background: rgba(255,255,255,0.05); padding: 0.25rem 0.5rem; border-radius: 4px; font-size: 0.8rem;">{m}</span>' for m in metadata)}
            </div>
        """
    
    # Screenshots
    if finding.get('screenshots'):
        html += '<div class="finding-field"><label>Screenshots</label>'
        for ss in finding.get('screenshots', []):
            if isinstance(ss, dict):
                html += f'<img src="{ss.get("data", ss.get("path", ""))}" alt="{ss.get("caption", "Screenshot")}" class="screenshot">'
            else:
                html += f'<img src="{ss}" alt="Screenshot" class="screenshot">'
        html += '</div>'
    
    html += """
        </div>
    </div>
    """
    
    return html


@app.get("/api/projects/{project_id}/export")
async def export_project_zip(project_id: str):
    """Export project data as a ZIP archive."""
    import zipfile
    import io
    from fastapi.responses import StreamingResponse
    
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    project = index["projects"][project_id]
    
    # Create ZIP in memory
    zip_buffer = io.BytesIO()
    
    with zipfile.ZipFile(zip_buffer, 'w', zipfile.ZIP_DEFLATED) as zf:
        # Add project metadata
        project_meta = {
            "id": project_id,
            "name": project.get("name"),
            "description": project.get("description"),
            "color": project.get("color"),
            "created_at": project.get("created_at"),
            "exported_at": datetime.now().isoformat()
        }
        zf.writestr("project.json", json.dumps(project_meta, indent=2))
        
        # Add VulnDB
        vulndb = project.get("vulndb", [])
        zf.writestr("vulndb.json", json.dumps(vulndb, indent=2))
        
        # Add tasks info
        task_ids = project.get("tasks", [])
        tasks_data = {}
        for task_id in task_ids:
            if task_id in index.get("tasks", {}):
                tasks_data[task_id] = index["tasks"][task_id]
        zf.writestr("tasks.json", json.dumps(tasks_data, indent=2))
        
        # Add reports
        for task_id in task_ids:
            task = index.get("tasks", {}).get(task_id, {})
            for report_path in task.get("reports", []):
                try:
                    path = Path(report_path)
                    if path.exists():
                        # Store in reports/ subfolder
                        zf.write(path, f"reports/{path.name}")
                except Exception as e:
                    print(f"Error adding report to ZIP: {e}")
        
        # Add a README
        readme = f"""# Project Export: {project.get('name', 'Unknown')}

Exported on: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}

## Contents

- `project.json` - Project metadata
- `vulndb.json` - Vulnerability database ({len(vulndb)} findings)
- `tasks.json` - Associated tasks ({len(task_ids)} tasks)
- `reports/` - Generated reports

## Statistics

- Total Vulnerabilities: {len(vulndb)}
- Critical: {sum(1 for v in vulndb if v.get('severity', '').lower() == 'critical')}
- High: {sum(1 for v in vulndb if v.get('severity', '').lower() == 'high')}
- Medium: {sum(1 for v in vulndb if v.get('severity', '').lower() == 'medium')}
- Low: {sum(1 for v in vulndb if v.get('severity', '').lower() == 'low')}
- Info: {sum(1 for v in vulndb if v.get('severity', '').lower() == 'info')}
"""
        zf.writestr("README.md", readme)
    
    zip_buffer.seek(0)
    
    # Generate filename
    safe_name = "".join(c if c.isalnum() or c in '-_' else '_' for c in project.get("name", "project"))
    filename = f"{safe_name}_export_{datetime.now().strftime('%Y%m%d_%H%M%S')}.zip"
    
    return StreamingResponse(
        zip_buffer,
        media_type="application/zip",
        headers={"Content-Disposition": f"attachment; filename={filename}"}
    )


@app.put("/api/tasks/{task_id}")
async def update_task(task_id: str, data: dict):
    """Update task metadata (prompt, label)."""
    index = load_reports_index()
    
    if task_id not in index.get("tasks", {}):
        return JSONResponse({"error": "Task not found"}, status_code=404)
    
    task = index["tasks"][task_id]
    
    if "prompt" in data:
        task["prompt"] = data["prompt"]
    if "label" in data:
        task["label"] = data["label"]
    
    save_reports_index(index)
    return JSONResponse({"success": True, "task": task})


@app.get("/api/tasks/{task_id}/details")
async def get_task_details(task_id: str):
    """Get detailed task info including reports and findings count."""
    index = load_reports_index()
    
    if task_id not in index.get("tasks", {}):
        return JSONResponse({"error": "Task not found"}, status_code=404)
    
    task = index["tasks"][task_id]
    
    # Get reports for this task
    reports = []
    for report_path in task.get("reports", []):
        try:
            path = Path(report_path)
            if path.exists():
                reports.append({
                    "path": report_path,
                    "name": path.name,
                    "size": path.stat().st_size,
                    "modified": datetime.fromtimestamp(path.stat().st_mtime).isoformat()
                })
        except Exception:
            pass
    
    # Try to get findings count from task data
    findings_count = task.get("findings_count", 0)
    
    return JSONResponse({
        "task_id": task_id,
        "prompt": task.get("prompt", ""),
        "label": task.get("label", "general"),
        "created_at": task.get("created_at"),
        "reports": reports,
        "findings_count": findings_count,
        "project_id": task.get("project_id")
    })


@app.post("/api/projects/{project_id}/tasks")
async def add_task_to_project(project_id: str, data: dict):
    """Add a task to a project and auto-parse findings to VulnDB."""
    task_id = data.get("task_id")
    if not task_id:
        return JSONResponse({"error": "task_id required"}, status_code=400)
    
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    # Remove task from any other project first
    for pid, proj in index["projects"].items():
        if task_id in proj.get("tasks", []):
            proj["tasks"].remove(task_id)
    
    # Add to new project
    if task_id not in index["projects"][project_id].get("tasks", []):
        index["projects"][project_id].setdefault("tasks", []).append(task_id)
    
    # Update task's project_id
    if task_id in index.get("tasks", {}):
        index["tasks"][task_id]["project_id"] = project_id
    
    # Update reports associated with this task
    for report in index.get("reports", []):
        if report.get("task_id") == task_id:
            report["project_id"] = project_id
    
    save_reports_index(index)
    
    # Auto-parse findings from task to VulnDB
    try:
        await auto_parse_task_findings_to_vulndb(project_id, task_id)
    except Exception as e:
        print(f"[ERROR] Failed to auto-parse findings: {e}")
    
    return JSONResponse({"success": True})


@app.post("/api/projects/{project_id}/parse-findings")
async def parse_project_findings(project_id: str):
    """Manually trigger parsing of findings from all project tasks to VulnDB."""
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    project = index["projects"][project_id]
    task_ids = project.get("tasks", [])
    
    if not task_ids:
        return JSONResponse({"findings_added": 0, "message": "No tasks in project"})
    
    # Count findings before parsing
    initial_count = len(project.get("vulndb", []))
    
    # Parse findings from each task
    for task_id in task_ids:
        try:
            await auto_parse_task_findings_to_vulndb(project_id, task_id)
        except Exception as e:
            print(f"[ERROR] Failed to parse findings from task {task_id}: {e}")
    
    # Reload index to get updated count
    index = load_reports_index()
    project = index["projects"].get(project_id, {})
    final_count = len(project.get("vulndb", []))
    
    findings_added = final_count - initial_count
    return JSONResponse({
        "success": True,
        "findings_added": findings_added,
        "total_vulnerabilities": final_count
    })


@app.delete("/api/projects/{project_id}/tasks/{task_id}")
async def remove_task_from_project(project_id: str, task_id: str):
    """Remove a task from a project."""
    index = load_reports_index()
    
    if project_id not in index.get("projects", {}):
        return JSONResponse({"error": "Project not found"}, status_code=404)
    
    project = index["projects"][project_id]
    if task_id in project.get("tasks", []):
        project["tasks"].remove(task_id)
    
    # Update task's project_id
    if task_id in index.get("tasks", {}):
        index["tasks"][task_id]["project_id"] = None
    
    # Update reports
    for report in index.get("reports", []):
        if report.get("task_id") == task_id:
            report["project_id"] = None
    
    save_reports_index(index)
    return JSONResponse({"success": True})

def add_report_to_index(report_path: str, task_id: str = None, task_prompt: str = None, 
                       task_label: str = None, project_id: str = None):
    """Add a report to the index with task/project association."""
    index = load_reports_index()
    
    # Create report entry
    report_entry = {
        "path": report_path,
        "task_id": task_id,
        "project_id": project_id,
        "added_at": datetime.now().isoformat()
    }
    
    # Add to reports list
    index["reports"].append(report_entry)
    
    # Update task info if provided
    if task_id:
        if task_id not in index["tasks"]:
            index["tasks"][task_id] = {
                "prompt": task_prompt or "Unknown task",
                "label": task_label or "general",
                "created_at": datetime.now().isoformat(),
                "reports": []
            }
        index["tasks"][task_id]["reports"].append(report_path)
    
    save_reports_index(index)
    return report_entry

@app.get("/api/reports")
async def get_reports(grouped: bool = True):
    """Get list of all generated reports, optionally grouped by task."""
    reports = []
    index = load_reports_index()
    tasks_data = index.get("tasks", {})
    projects_data = index.get("projects", {})
    
    # Only include indexed reports that exist on filesystem
    for report_entry in index.get("reports", []):
        path_str = report_entry.get("path", "")
        file_path = Path(path_str)
        
        if not file_path.exists():
            continue
            
        try:
            stat = file_path.stat()
            ext = file_path.suffix.lower().lstrip('.')
            if ext not in ['html', 'pdf', 'md', 'json', 'txt', 'xml', 'csv']:
                continue
                
            reports.append({
                "name": file_path.name,
                "path": path_str,
                "type": ext,
                "size": stat.st_size,
                "modified": datetime.fromtimestamp(stat.st_mtime).isoformat(),
                "task_id": report_entry.get("task_id"),
                "project_id": report_entry.get("project_id")
            })
        except Exception:
            pass
    
    # Sort by modified date descending
    reports.sort(key=lambda x: x.get("modified", ""), reverse=True)
    
    if not grouped:
        return JSONResponse(reports)
    
    # Group reports by task
    grouped_reports = {
        "ungrouped": [],
        "tasks": {},
        "projects": projects_data
    }
    
    for report in reports:
        task_id = report.get("task_id")
        if task_id and task_id in tasks_data:
            if task_id not in grouped_reports["tasks"]:
                grouped_reports["tasks"][task_id] = {
                    **tasks_data[task_id],
                    "reports": []
                }
            grouped_reports["tasks"][task_id]["reports"].append(report)
        else:
            grouped_reports["ungrouped"].append(report)
    
    return JSONResponse(grouped_reports)

@app.get("/api/reports/view")
async def view_report(path: str):
    """View report content."""
    file_path = Path(path)
    
    if not file_path.exists():
        return JSONResponse({"error": "Report not found"}, status_code=404)
    
    # Security check - only allow files in known directories
    allowed_parents = [REPORTS_DIR.resolve(), Path("output").resolve(), Path("reports").resolve()]
    if not any(str(file_path.resolve()).startswith(str(p)) for p in allowed_parents if p.exists()):
        return JSONResponse({"error": "Access denied"}, status_code=403)
    
    try:
        content = file_path.read_text(encoding='utf-8', errors='replace')
        return JSONResponse({
            "name": file_path.name,
            "type": file_path.suffix.lower().lstrip('.'),
            "content": content[:500000]  # Limit to 500KB
        })
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.get("/api/reports/download")
async def download_report(path: str):
    """Download a report file."""
    from fastapi.responses import FileResponse
    
    file_path = Path(path)
    
    if not file_path.exists():
        return JSONResponse({"error": "Report not found"}, status_code=404)
    
    return FileResponse(
        path=file_path,
        filename=file_path.name,
        media_type='application/octet-stream'
    )

@app.delete("/api/reports/delete")
async def delete_report(data: dict):
    """Delete a report file."""
    path = data.get("path")
    if not path:
        return JSONResponse({"error": "Path required"}, status_code=400)
    
    file_path = Path(path)
    
    if not file_path.exists():
        return JSONResponse({"error": "Report not found"}, status_code=404)
    
    try:
        file_path.unlink()
        return JSONResponse({"success": True})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.post("/api/reports/save")
async def save_report(data: dict):
    """Save a report to disk with optional task association."""
    content = data.get("content", "")
    name = data.get("name", "report")
    format_type = data.get("format", "html")
    task_id = data.get("task_id")
    task_prompt = data.get("task_prompt")
    task_label = data.get("task_label")
    project_id = data.get("project_id")
    
    if not content:
        return JSONResponse({"error": "Content required"}, status_code=400)
    
    # Generate filename
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    safe_name = "".join(c if c.isalnum() or c in '-_' else '_' for c in name)
    filename = f"{safe_name}_{timestamp}.{format_type}"
    
    file_path = REPORTS_DIR / filename
    
    try:
        file_path.write_text(content, encoding='utf-8')
        
        # Add to reports index with task association
        add_report_to_index(
            str(file_path), 
            task_id=task_id,
            task_prompt=task_prompt,
            task_label=task_label,
            project_id=project_id
        )
        
        return JSONResponse({
            "success": True,
            "path": str(file_path),
            "filename": filename,
            "task_id": task_id
        })
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

# Endpoint to assign existing reports to tasks
@app.post("/api/reports/assign-task")
async def assign_report_to_task(data: dict):
    """Assign an existing report to a task."""
    report_path = data.get("path")
    task_id = data.get("task_id")
    task_prompt = data.get("task_prompt")
    task_label = data.get("task_label")
    
    if not report_path:
        return JSONResponse({"error": "Report path required"}, status_code=400)
    
    index = load_reports_index()
    
    # Check if report is already in index
    found = False
    for r in index.get("reports", []):
        if r["path"] == report_path:
            r["task_id"] = task_id
            found = True
            break
    
    if not found:
        # Add new entry
        index["reports"].append({
            "path": report_path,
            "task_id": task_id,
            "project_id": None,
            "added_at": datetime.now().isoformat()
        })
    
    # Update task info
    if task_id:
        if task_id not in index["tasks"]:
            index["tasks"][task_id] = {
                "prompt": task_prompt or "Unknown task",
                "label": task_label or "general",
                "created_at": datetime.now().isoformat(),
                "reports": []
            }
        if report_path not in index["tasks"][task_id]["reports"]:
            index["tasks"][task_id]["reports"].append(report_path)
    
    save_reports_index(index)
    return JSONResponse({"success": True})

# ============== NOTES ENDPOINTS ==============

NOTES_DIR = Path("data/notes")
NOTES_DIR.mkdir(parents=True, exist_ok=True)
NOTES_ATTACHMENTS_DIR = NOTES_DIR / "attachments"
NOTES_ATTACHMENTS_DIR.mkdir(parents=True, exist_ok=True)

# Notes store file
NOTES_INDEX_FILE = NOTES_DIR / "index.json"

def load_notes_index():
    """Load notes index from file."""
    if NOTES_INDEX_FILE.exists():
        try:
            return json.loads(NOTES_INDEX_FILE.read_text())
        except:
            pass
    return {"folders": [], "files": [], "next_id": 1}

def save_notes_index(index):
    """Save notes index to file."""
    NOTES_INDEX_FILE.write_text(json.dumps(index, indent=2))

notes_index = load_notes_index()

@app.get("/api/notes")
async def get_notes():
    """Get notes tree structure - always reload from file to pick up agent changes."""
    global notes_index
    notes_index = load_notes_index()
    return JSONResponse(notes_index)

@app.post("/api/notes")
async def create_note(data: dict):
    """Create a new note."""
    global notes_index
    
    name = data.get("name", "Untitled")
    folder_id = data.get("folder_id")
    content = data.get("content", "")
    
    note_id = str(notes_index.get("next_id", 1))
    notes_index["next_id"] = int(note_id) + 1
    
    # Create note file
    note_file = NOTES_DIR / f"{note_id}.json"
    note_data = {
        "id": note_id,
        "name": name,
        "content": content,
        "attachments": [],
        "created_at": datetime.now().isoformat(),
        "updated_at": datetime.now().isoformat()
    }
    note_file.write_text(json.dumps(note_data, indent=2))
    
    # Add to index
    note_entry = {"id": note_id, "name": name, "type": "file"}
    
    if folder_id:
        # Add to folder recursively
        def add_to_folder(folders, target_id, entry):
            for folder in folders:
                if folder.get("id") == target_id:
                    if "children" not in folder:
                        folder["children"] = []
                    folder["children"].append(entry)
                    return True
                if "children" in folder:
                    if add_to_folder([c for c in folder["children"] if c.get("type") == "folder"], target_id, entry):
                        return True
            return False
        
        # Also store folder_id in the note file
        note_data["folder_id"] = folder_id
        note_file.write_text(json.dumps(note_data, indent=2))
        
        if not add_to_folder(notes_index.get("folders", []), folder_id, note_entry):
            # Folder not found, add to root
            notes_index["files"].append(note_entry)
    else:
        notes_index["files"].append(note_entry)
    
    save_notes_index(notes_index)
    return JSONResponse(note_data)

@app.get("/api/notes/{note_id}")
async def get_note(note_id: str):
    """Get a specific note."""
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if not note_file.exists():
        return JSONResponse({"error": "Note not found"}, status_code=404)
    
    try:
        note_data = json.loads(note_file.read_text())
        return JSONResponse(note_data)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.put("/api/notes/{note_id}")
async def update_note(note_id: str, data: dict):
    """Update a note."""
    global notes_index
    
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if not note_file.exists():
        return JSONResponse({"error": "Note not found"}, status_code=404)
    
    try:
        note_data = json.loads(note_file.read_text())
        
        if "name" in data:
            note_data["name"] = data["name"]
            # Update index
            for f in notes_index.get("files", []):
                if f.get("id") == note_id:
                    f["name"] = data["name"]
                    break
            save_notes_index(notes_index)
        
        if "content" in data:
            note_data["content"] = data["content"]
        
        note_data["updated_at"] = datetime.now().isoformat()
        note_file.write_text(json.dumps(note_data, indent=2))
        
        return JSONResponse({"success": True})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.delete("/api/notes/{note_id}")
async def delete_note(note_id: str):
    """Delete a note."""
    global notes_index
    
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if note_file.exists():
        note_file.unlink()
    
    # Remove from index
    notes_index["files"] = [f for f in notes_index.get("files", []) if f.get("id") != note_id]
    save_notes_index(notes_index)
    
    return JSONResponse({"success": True})

@app.post("/api/notes/{note_id}/version")
async def save_note_version(note_id: str, data: dict = None):
    """Save a version of the note."""
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if not note_file.exists():
        return JSONResponse({"error": "Note not found"}, status_code=404)
    
    try:
        note_data = json.loads(note_file.read_text())
        
        # Initialize versions array if not exists
        if "versions" not in note_data:
            note_data["versions"] = []
        
        # Create version snapshot
        version_name = (data or {}).get("name", f"Version {len(note_data['versions']) + 1}")
        version = {
            "id": str(uuid.uuid4()),
            "name": version_name,
            "content": note_data.get("content", ""),
            "created_at": datetime.now().isoformat()
        }
        
        # Add version (keep max 20 versions)
        note_data["versions"].insert(0, version)
        if len(note_data["versions"]) > 20:
            note_data["versions"] = note_data["versions"][:20]
        
        note_file.write_text(json.dumps(note_data, indent=2))
        
        return JSONResponse({"success": True, "version": version})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.get("/api/notes/{note_id}/versions")
async def get_note_versions(note_id: str):
    """Get all versions of a note."""
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if not note_file.exists():
        return JSONResponse({"error": "Note not found"}, status_code=404)
    
    try:
        note_data = json.loads(note_file.read_text())
        versions = note_data.get("versions", [])
        # Return versions without full content for listing
        versions_summary = [{
            "id": v["id"],
            "name": v["name"],
            "created_at": v["created_at"]
        } for v in versions]
        return JSONResponse({"versions": versions_summary})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.post("/api/notes/{note_id}/restore/{version_id}")
async def restore_note_version(note_id: str, version_id: str):
    """Restore a specific version of a note."""
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if not note_file.exists():
        return JSONResponse({"error": "Note not found"}, status_code=404)
    
    try:
        note_data = json.loads(note_file.read_text())
        versions = note_data.get("versions", [])
        
        # Find the version
        version = next((v for v in versions if v["id"] == version_id), None)
        if not version:
            return JSONResponse({"error": "Version not found"}, status_code=404)
        
        # Save current content as a version before restoring
        current_version = {
            "id": str(uuid.uuid4()),
            "name": f"Auto-save before restore",
            "content": note_data.get("content", ""),
            "created_at": datetime.now().isoformat()
        }
        note_data["versions"].insert(0, current_version)
        if len(note_data["versions"]) > 20:
            note_data["versions"] = note_data["versions"][:20]
        
        # Restore the selected version
        note_data["content"] = version["content"]
        note_data["updated_at"] = datetime.now().isoformat()
        
        note_file.write_text(json.dumps(note_data, indent=2))
        
        return JSONResponse({"success": True, "content": version["content"]})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.delete("/api/notes/{note_id}/version/{version_id}")
async def delete_note_version(note_id: str, version_id: str):
    """Delete a specific version of a note."""
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if not note_file.exists():
        return JSONResponse({"error": "Note not found"}, status_code=404)
    
    try:
        note_data = json.loads(note_file.read_text())
        note_data["versions"] = [v for v in note_data.get("versions", []) if v["id"] != version_id]
        note_file.write_text(json.dumps(note_data, indent=2))
        return JSONResponse({"success": True})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.post("/api/notes/folder")
async def create_note_folder(data: dict):
    """Create a new folder."""
    global notes_index
    
    name = data.get("name", "New Folder")
    
    # Check for duplicate folder name at root level
    for existing_folder in notes_index.get("folders", []):
        if existing_folder.get("name", "").lower() == name.lower():
            return JSONResponse(
                {"error": f"Folder '{name}' already exists"},
                status_code=400
            )
    
    folder_id = str(notes_index.get("next_id", 1))
    notes_index["next_id"] = int(folder_id) + 1
    
    folder_entry = {
        "id": folder_id,
        "name": name,
        "type": "folder",
        "path": folder_id,
        "children": []
    }
    
    notes_index["folders"].append(folder_entry)
    save_notes_index(notes_index)
    
    return JSONResponse(folder_entry)


@app.delete("/api/notes/folder/{folder_id}")
async def delete_note_folder(folder_id: str):
    """Delete a folder and all its contents."""
    global notes_index
    
    def delete_folder_recursive(folders, target_id):
        for i, folder in enumerate(folders):
            if folder.get("id") == target_id or folder.get("path") == target_id:
                # Delete all notes in this folder and subfolders
                deleted_folder = folders.pop(i)
                delete_folder_contents(deleted_folder)
                return True
            # Check children
            if "children" in folder:
                child_folders = [c for c in folder["children"] if c.get("type") == "folder"]
                if delete_folder_recursive(child_folders, target_id):
                    folder["children"] = [c for c in folder["children"] if c.get("type") != "folder" or c.get("id") != target_id]
                    return True
        return False
    
    def delete_folder_contents(folder):
        # Delete notes in folder
        for child in folder.get("children", []):
            if child.get("type") == "folder":
                delete_folder_contents(child)
            else:
                # Delete note file
                note_id = child.get("id")
                if note_id:
                    note_file = NOTES_DIR / f"{note_id}.json"
                    if note_file.exists():
                        note_file.unlink()
                    # Remove from files index
                    notes_index["files"] = [f for f in notes_index.get("files", []) if f.get("id") != note_id]
    
    try:
        if delete_folder_recursive(notes_index.get("folders", []), folder_id):
            save_notes_index(notes_index)
            return JSONResponse({"success": True})
        return JSONResponse({"error": "Folder not found"}, status_code=404)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


@app.put("/api/notes/folder/{folder_id}")
async def rename_note_folder(folder_id: str, data: dict):
    """Rename a folder."""
    global notes_index
    
    new_name = data.get("name")
    if not new_name:
        return JSONResponse({"error": "Name required"}, status_code=400)
    
    def rename_folder_recursive(folders, target_id, new_name):
        for folder in folders:
            if folder.get("id") == target_id or folder.get("path") == target_id:
                folder["name"] = new_name
                return True
            if "children" in folder:
                child_folders = [c for c in folder["children"] if c.get("type") == "folder"]
                if rename_folder_recursive(child_folders, target_id, new_name):
                    return True
        return False
    
    try:
        if rename_folder_recursive(notes_index.get("folders", []), folder_id, new_name):
            save_notes_index(notes_index)
            return JSONResponse({"success": True, "name": new_name})
        return JSONResponse({"error": "Folder not found"}, status_code=404)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


@app.post("/api/notes/{note_id}/attachments")
async def upload_note_attachments(note_id: str, files: List[UploadFile] = File(...)):
    """Upload attachments to a note."""
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if not note_file.exists():
        return JSONResponse({"error": "Note not found"}, status_code=404)
    
    try:
        note_data = json.loads(note_file.read_text())
        attachments = note_data.get("attachments", [])
        
        for file in files:
            att_id = str(uuid.uuid4())[:8]
            att_path = NOTES_ATTACHMENTS_DIR / f"{note_id}_{att_id}_{file.filename}"
            
            content = await file.read()
            att_path.write_bytes(content)
            
            attachments.append({
                "id": att_id,
                "name": file.filename,
                "path": str(att_path),
                "size": len(content)
            })
        
        note_data["attachments"] = attachments
        note_file.write_text(json.dumps(note_data, indent=2))
        
        return JSONResponse(attachments)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.delete("/api/notes/{note_id}/attachments/{att_id}")
async def delete_note_attachment(note_id: str, att_id: str):
    """Delete an attachment from a note."""
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if not note_file.exists():
        return JSONResponse({"error": "Note not found"}, status_code=404)
    
    try:
        note_data = json.loads(note_file.read_text())
        attachments = note_data.get("attachments", [])
        
        # Find and remove attachment
        att_to_remove = None
        for att in attachments:
            if att.get("id") == att_id:
                att_to_remove = att
                break
        
        if not att_to_remove:
            return JSONResponse({"error": "Attachment not found"}, status_code=404)
        
        # Delete file
        att_path = Path(att_to_remove.get("path", ""))
        if att_path.exists():
            att_path.unlink()
        
        # Remove from note
        attachments.remove(att_to_remove)
        note_data["attachments"] = attachments
        note_file.write_text(json.dumps(note_data, indent=2))
        
        return JSONResponse({"success": True})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.post("/api/notes/{note_id}/process")
async def process_note_with_ai(note_id: str, data: dict):
    """Process note content with AI."""
    action = data.get("action", "")
    content = data.get("content", "")
    
    if not action or not content:
        return JSONResponse({"error": "Action and content required"}, status_code=400)
    
    # Use the agent to process
    try:
        prompt = f"Please {action} the following text. Return only the processed result, no explanations:\n\n{content}"
        
        # Create a simple processing agent or use existing
        if agent:
            result = agent.run(prompt)
            return JSONResponse({"content": str(result)})
        else:
            return JSONResponse({"error": "Agent not available"}, status_code=503)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.get("/api/notes/{note_id}/export")
async def export_note(note_id: str, format: str = "html"):
    """Export note in various formats."""
    from fastapi.responses import Response
    
    note_file = NOTES_DIR / f"{note_id}.json"
    
    if not note_file.exists():
        return JSONResponse({"error": "Note not found"}, status_code=404)
    
    try:
        note_data = json.loads(note_file.read_text())
        name = note_data.get("name", "note")
        content = note_data.get("content", "")
        
        if format == "html":
            # Wrap in basic HTML
            html_content = f"""<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>{name}</title>
    <style>
        body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 800px; margin: 40px auto; padding: 20px; line-height: 1.6; }}
        h1, h2, h3 {{ color: #333; }}
        code {{ background: #f4f4f4; padding: 2px 6px; border-radius: 4px; }}
        pre {{ background: #f4f4f4; padding: 16px; border-radius: 8px; overflow-x: auto; }}
        blockquote {{ border-left: 4px solid #22c55e; margin: 16px 0; padding-left: 16px; color: #666; }}
    </style>
</head>
<body>
    <h1>{name}</h1>
    {content}
</body>
</html>"""
            return Response(
                content=html_content,
                media_type="text/html",
                headers={"Content-Disposition": f'attachment; filename="{name}.html"'}
            )
        
        elif format == "md":
            # Convert HTML to Markdown (basic)
            import re
            md_content = content
            md_content = re.sub(r'<h1[^>]*>(.*?)</h1>', r'# \1\n', md_content)
            md_content = re.sub(r'<h2[^>]*>(.*?)</h2>', r'## \1\n', md_content)
            md_content = re.sub(r'<h3[^>]*>(.*?)</h3>', r'### \1\n', md_content)
            md_content = re.sub(r'<strong>(.*?)</strong>', r'**\1**', md_content)
            md_content = re.sub(r'<b>(.*?)</b>', r'**\1**', md_content)
            md_content = re.sub(r'<em>(.*?)</em>', r'*\1*', md_content)
            md_content = re.sub(r'<i>(.*?)</i>', r'*\1*', md_content)
            md_content = re.sub(r'<code>(.*?)</code>', r'`\1`', md_content)
            md_content = re.sub(r'<br\s*/?>', '\n', md_content)
            md_content = re.sub(r'<[^>]+>', '', md_content)  # Remove remaining HTML
            md_content = f"# {name}\n\n{md_content}"
            
            return Response(
                content=md_content,
                media_type="text/markdown",
                headers={"Content-Disposition": f'attachment; filename="{name}.md"'}
            )
        
        elif format == "txt":
            # Plain text - strip all HTML
            import re
            txt_content = re.sub(r'<[^>]+>', '', content)
            txt_content = f"{name}\n{'=' * len(name)}\n\n{txt_content}"
            
            return Response(
                content=txt_content,
                media_type="text/plain",
                headers={"Content-Disposition": f'attachment; filename="{name}.txt"'}
            )
        
        elif format == "pdf":
            # Generate PDF using subprocess to avoid sync_playwright in async context
            import tempfile
            import subprocess
            import sys
            
            # Create HTML content for PDF
            html_for_pdf = f"""<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>{name}</title>
    <style>
        @page {{ size: A4; margin: 1.5cm; }}
        body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 100%; margin: 0; padding: 20px; line-height: 1.6; font-size: 12pt; color: #333; background: white; }}
        h1 {{ color: #1a1a1a; font-size: 24pt; margin-bottom: 0.5em; }}
        h2 {{ color: #333; font-size: 18pt; }}
        h3 {{ color: #444; font-size: 14pt; }}
        code {{ background: #f4f4f4; padding: 2px 6px; border-radius: 4px; font-family: 'Consolas', monospace; }}
        pre {{ background: #f4f4f4; padding: 16px; border-radius: 8px; overflow-x: auto; }}
        blockquote {{ border-left: 4px solid #22c55e; margin: 16px 0; padding-left: 16px; color: #666; }}
        table {{ width: 100%; border-collapse: collapse; margin: 1em 0; }}
        th, td {{ border: 1px solid #ddd; padding: 8px; text-align: left; }}
        th {{ background-color: #f5f5f5; }}
        img {{ max-width: 100%; height: auto; }}
        @media print {{ body {{ print-color-adjust: exact; -webkit-print-color-adjust: exact; }} }}
    </style>
</head>
<body>
    <h1>{name}</h1>
    {content}
</body>
</html>"""
            
            try:
                # Create temp files for HTML input and PDF output
                with tempfile.NamedTemporaryFile(mode='w', suffix='.html', delete=False, encoding='utf-8') as html_file:
                    html_file.write(html_for_pdf)
                    html_path = html_file.name
                
                pdf_path = html_path.replace('.html', '.pdf')
                
                # Use subprocess to run playwright PDF generation script
                script = f'''
import sys
try:
    from playwright.sync_api import sync_playwright
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()
        with open("{html_path}", "r", encoding="utf-8") as f:
            page.set_content(f.read())
        page.pdf(path="{pdf_path}", format="A4", print_background=True)
        browser.close()
    print("SUCCESS")
except Exception as e:
    print(f"ERROR: {{e}}")
    sys.exit(1)
'''
                
                result = subprocess.run(
                    [sys.executable, '-c', script],
                    capture_output=True,
                    text=True,
                    timeout=60
                )
                
                if result.returncode == 0 and os.path.exists(pdf_path):
                    with open(pdf_path, 'rb') as f:
                        pdf_bytes = f.read()
                    
                    # Cleanup temp files
                    try:
                        os.unlink(html_path)
                        os.unlink(pdf_path)
                    except:
                        pass
                    
                    return Response(
                        content=pdf_bytes,
                        media_type="application/pdf",
                        headers={"Content-Disposition": f'attachment; filename="{name}.pdf"'}
                    )
                else:
                    # Cleanup and fallback
                    try:
                        os.unlink(html_path)
                    except:
                        pass
                    raise Exception(result.stderr or "PDF generation failed")
                    
            except Exception as e:
                # Fallback to HTML with print instructions
                html_for_pdf = f"""<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>{name}</title>
    <style>
        @page {{ size: A4; margin: 1.5cm; }}
        body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 100%; margin: 0; padding: 20px; line-height: 1.6; font-size: 12pt; }}
        h1 {{ color: #1a1a1a; font-size: 24pt; margin-bottom: 0.5em; }}
        h2 {{ color: #333; font-size: 18pt; }}
        h3 {{ color: #444; font-size: 14pt; }}
        code {{ background: #f4f4f4; padding: 2px 6px; border-radius: 4px; font-family: 'Consolas', monospace; }}
        pre {{ background: #f4f4f4; padding: 16px; border-radius: 8px; overflow-x: auto; }}
        blockquote {{ border-left: 4px solid #22c55e; margin: 16px 0; padding-left: 16px; color: #666; }}
        table {{ width: 100%; border-collapse: collapse; margin: 1em 0; }}
        th, td {{ border: 1px solid #ddd; padding: 8px; text-align: left; }}
        th {{ background-color: #f5f5f5; }}
        @media print {{ body {{ print-color-adjust: exact; -webkit-print-color-adjust: exact; }} }}
        .print-notice {{ background: #fef3c7; border: 1px solid #f59e0b; padding: 16px; border-radius: 8px; margin-bottom: 20px; }}
        @media print {{ .print-notice {{ display: none; }} }}
    </style>
</head>
<body>
    <div class="print-notice">
        <strong>Note:</strong> PDF generation requires Playwright. Use Ctrl+P (Cmd+P on Mac) to print this page as PDF.<br>
        <small>Error: {str(e)}</small>
    </div>
    <h1>{name}</h1>
    {content}
</body>
</html>"""
                return Response(
                    content=html_for_pdf,
                    media_type="text/html",
                    headers={"Content-Disposition": f'attachment; filename="{name}_print_as_pdf.html"'}
                )
        
        else:
            return JSONResponse({"error": f"Unsupported format: {format}"}, status_code=400)
            
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)

@app.post("/api/notes/{note_id}/move")
async def move_note(note_id: str, data: dict):
    """Move a note or folder to a different parent folder."""
    global notes_index
    target_folder_id = data.get("target_folder_id")  # None means root
    
    note_file = NOTES_DIR / f"{note_id}.json"
    is_folder = False
    note_data = None
    
    # Check if it's a note file or a folder
    if note_file.exists():
        # It's a note file
        try:
            note_data = json.loads(note_file.read_text())
            # Update parent folder in note file
            note_data["folder_id"] = target_folder_id
            note_data["updated_at"] = datetime.now().isoformat()
            note_file.write_text(json.dumps(note_data, indent=2))
        except Exception as e:
            return JSONResponse({"error": f"Failed to update note file: {str(e)}"}, status_code=500)
    else:
        # Check if it's a folder in the index
        def find_folder_in_index(items, folder_id):
            for item in items:
                if item.get("id") == folder_id and item.get("type") == "folder":
                    return True
                if item.get("type") == "folder" and "children" in item:
                    if find_folder_in_index(item["children"], folder_id):
                        return True
            return False
        
        is_folder = find_folder_in_index(notes_index.get("folders", []), note_id)
        if not is_folder:
            return JSONResponse({"error": "Note or folder not found"}, status_code=404)
    
    try:
        # Helper to remove item from current location in index (recursively searches all folders)
        def remove_from_index(items, nid):
            for i, item in enumerate(items):
                if item.get("id") == nid:
                    return items.pop(i)
                if item.get("type") == "folder" and "children" in item:
                    result = remove_from_index(item["children"], nid)
                    if result:
                        return result
            return None
        
        # Helper to add item to target folder
        def add_to_folder(folders, target_id, entry):
            for folder in folders:
                if folder.get("id") == target_id:
                    if "children" not in folder:
                        folder["children"] = []
                    folder["children"].append(entry)
                    return True
                if "children" in folder:
                    if add_to_folder([c for c in folder["children"] if c.get("type") == "folder"], target_id, entry):
                        return True
            return False
        
        # Prevent moving a folder into itself or its children
        if is_folder and target_folder_id:
            def is_descendant(folder_id, potential_ancestor_id):
                """Check if folder_id is a descendant of potential_ancestor_id."""
                def find_in_children(items, pid):
                    for item in items:
                        if item.get("id") == pid:
                            # Check if folder_id is in this folder's children
                            def check_children(children, fid):
                                for child in children:
                                    if child.get("id") == fid:
                                        return True
                                    if child.get("type") == "folder" and "children" in child:
                                        if check_children(child["children"], fid):
                                            return True
                                return False
                            return check_children(item.get("children", []), folder_id)
                        if item.get("type") == "folder" and "children" in item:
                            result = find_in_children(item["children"], pid)
                            if result:
                                return result
                    return False
                return find_in_children(notes_index.get("folders", []), potential_ancestor_id)
            
            if note_id == target_folder_id or is_descendant(target_folder_id, note_id):
                return JSONResponse({"error": "Cannot move folder into itself or its children"}, status_code=400)
        
        # Remove from current location - check root files first
        note_entry = remove_from_index(notes_index.get("files", []), note_id)
        
        # If not found in root files, check root folders
        if not note_entry:
            note_entry = remove_from_index(notes_index.get("folders", []), note_id)
        
        if not note_entry:
            # Entry not found in index, which shouldn't happen but reconstruct if we have data
            if is_folder:
                return JSONResponse({"error": "Folder entry not found in index"}, status_code=404)
            note_entry = {"id": note_id, "name": note_data.get("name", "Note") if note_data else "Note", "type": "file"}
        
        # Add to new location
        if target_folder_id:
            if not add_to_folder(notes_index.get("folders", []), target_folder_id, note_entry):
                # Target folder not found, add to root based on type
                if note_entry.get("type") == "folder":
                    notes_index["folders"].append(note_entry)
                else:
                    notes_index["files"].append(note_entry)
        else:
            # Move to root - add to appropriate list based on type
            if note_entry.get("type") == "folder":
                notes_index["folders"].append(note_entry)
            else:
                notes_index["files"].append(note_entry)
        
        save_notes_index(notes_index)
        
        return JSONResponse({"success": True, "note_id": note_id, "new_folder": target_folder_id})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return JSONResponse({"error": str(e)}, status_code=500)

